package com.mishisql.generated;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.sql.*;

public class ComprasCrud extends JFrame {
    private JTextField idField;
    private JTextField usuarioIdField;
    private JTextField productoField;
    private JTextField precioField;
    private JButton insertBtn, updateBtn;

    public ComprasCrud() {
        super("CRUD - Compras");
        setLayout(new GridLayout(5, 2));
        add(new JLabel("id:"));
        idField = new JTextField();
        add(idField);
        add(new JLabel("usuarioId:"));
        usuarioIdField = new JTextField();
        add(usuarioIdField);
        add(new JLabel("producto:"));
        productoField = new JTextField();
        add(productoField);
        add(new JLabel("precio:"));
        precioField = new JTextField();
        add(precioField);
        insertBtn = new JButton("Insert");
        updateBtn = new JButton("Update");
        add(insertBtn);
        add(updateBtn);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        pack(); setVisible(true);
        insertBtn.addActionListener(e -> {
            try (Connection conn = DriverManager.getConnection(JDBC_URL, JDBC_USER, JDBC_PASS)) {
                String sql = "INSERT INTO Compras (id,usuarioId,producto,precio) VALUES (?,?,?,?)";
                PreparedStatement ps = conn.prepareStatement(sql);

 ps.setString(1, idField.getText());
                ps.setString(2, usuarioIdField.getText());
                ps.setString(3, productoField.getText());
                ps.setString(4, precioField.getText());
                ps.executeUpdate();
                JOptionPane.showMessageDialog(null, "Success!");
            } catch (SQLException ex) { ex.printStackTrace(); }
        });
        updateBtn.addActionListener(e -> {
            try (Connection conn = DriverManager.getConnection(JDBC_URL, JDBC_USER, JDBC_PASS)) {
                String sql = "UPDATE Compras SET usuarioId=?,producto=?,precio=? WHERE id=?";
                PreparedStatement ps = conn.prepareStatement(sql);
                ps.setString(1, idField.getText());
                ps.setString(2, usuarioIdField.getText());
                ps.setString(3, productoField.getText());

     ps.setString(4, precioField.getText());
                ps.executeUpdate();
                JOptionPane.showMessageDialog(null, "Success!");
            } catch (SQLException ex) { ex.printStackTrace(); }
        });
    }

    public static void main(String[] args) { new ComprasCrud(); }
    private static String capitalize(String s) { return s.substring(0,1).toUpperCase() + s.substring(1); }
}

